import * as THREE from 'three/webgpu';

export default function createNode(config: NodeConfig, ctx: NodeContext): THREE.Object3D {
  const group = new THREE.Group();

  // Load texture (cached via ctx.textureLoader)
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create material: unlit textured plane
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
    transparent: true
  });

  // Create geometry: plane with 512:320 aspect ratio (1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1);
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position, rotation, and scale from config
  if (config.scenePosition) {
    const sp = config.scenePosition;
    mesh.position.set(sp.x ?? 0, sp.y ?? 0, sp.z ?? 0);

    if (sp.rotationXYZ) {
      mesh.rotation.order = 'XYZ';
      mesh.rotation.x = sp.rotationXYZ.x ?? 0;
      mesh.rotation.y = sp.rotationXYZ.y ?? 0;
      mesh.rotation.z = sp.rotationXYZ.z ?? 0;
    }

    if (sp.scaleXYZ) {
      mesh.scale.set(
        sp.scaleXYZ.x ?? 1,
        sp.scaleXYZ.y ?? 1,
        sp.scaleXYZ.z ?? 1
      );
    }
  }

  group.add(mesh);

  // Setup cleanup function for resource disposal
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Setup empty handlers object
  group.userData.handlers = {};

  return group;
}
